// Operators at a training (docs/spec/operators.md 干员-1…干员-3): an operator's training data, generated by @aue/data
// into data/operators/<id>.json, and a build — elite, level, potential, trust, skill and skill level — as @aue/sim's
// operator. The data is loaded per operator, on first use.
import index from '../data/operators/index.json' with { type: 'json' };
import { withTrait } from './traits.js';
import { skillDefOf } from './skills.js';

/** @typedef {import('@aue/sim').OperatorDef} OperatorDef */
/**
 * A training (干员-1, 干员-2): elite phase 0–2, level, potential 1–6, trust 0–200 (%), the skill slot (0-based; −1 for
 * none) and its level 1–10 (8–10: 专精 1–3).
 * @typedef {{ elite: number, level: number, potential: number, trust: number, skill: number, skillLevel: number }} Build
 */
/** @typedef {Record<string, number>} Stats */
/**
 * An operator's training data (干员-1…干员-3), as @aue/data writes it.
 * @typedef {{ name: string, position: 'MELEE' | 'RANGED', profession: string, branch: string, rarity: number,
 *   phases: { maxLevel: number, range: { row: number, col: number }[], frames: { level: number, stats: Stats }[] }[],
 *   favor: { level: number, stats: Stats } | null, potentials: Stats[],
 *   skills: { id: string, phase: number, levels: import('./skills.js').SkillLevel[] }[],
 *   traits: { phase: number, level: number, potential: number, bb: Stats }[] }} Training
 */

/** Every operator there is training data for, by id: name, rarity, profession, branch. */
export const ROSTER = /** @type {Readonly<Record<string, { name: string, rarity: number, profession: string, branch: string }>>} */ (index.operators);
/** Where the training data comes from: the ArknightsGameData commit. */
export const rosterSource = index.source;

/** An operator's training data (干员-1), loaded on first use. @param {string} id @returns {Promise<Training>} */
export async function loadTraining(id) {
  if (!Object.hasOwn(ROSTER, id)) throw new RangeError(`no operator ${id}`);
  return (await import(`../data/operators/${id}.json`, { with: { type: 'json' } })).default;
}

/** @param {number} v @param {number} lo @param {number} hi */
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

/**
 * The keyframes' attributes at a level (干员-1): linear between the two around it, not rounded.
 * @param {{ level: number, stats: Stats }[]} frames @param {number} level @returns {Stats}
 */
function atLevel(frames, level) {
  const i = Math.max(0, frames.findIndex((f) => f.level >= level) - 1), a = frames[i], b = frames[Math.min(i + 1, frames.length - 1)];
  const t = b.level === a.level ? 0 : (level - a.level) / (b.level - a.level);
  return Object.fromEntries(Object.keys(a.stats).map((k) => [k, a.stats[k] + (b.stats[k] - a.stats[k]) * t]));
}

/**
 * The attributes at a training (干员-1): elite and level, then trust, then potential.
 * @param {Training} t @param {Build} b @returns {Stats}
 */
function statsAt(t, b) {
  const phase = t.phases[b.elite], out = atLevel(phase.frames, clamp(b.level, 1, phase.maxLevel));
  if (t.favor) {
    const share = clamp(b.trust, 0, 100) / 100;
    for (const [k, v] of Object.entries(t.favor.stats)) out[k] += v * share;
  }
  for (const p of t.potentials.slice(0, clamp(b.potential, 1, 6) - 1)) for (const [k, v] of Object.entries(p)) out[k] = (out[k] ?? 0) + v;
  return out;
}

/** The trait blackboard at a training (干员-3): the last candidate unlocked. @param {Training} t @param {Build} b */
export function traitAt(t, b) {
  const open = t.traits.filter((c) => (c.phase < b.elite || (c.phase === b.elite && c.level <= b.level)) && c.potential <= b.potential - 1);
  return open.at(-1)?.bb ?? {};
}

/**
 * An operator at a training (干员-1…干员-3) as @aue/sim reads it: its attributes, the elite phase's range, its branch's
 * trait (职业-7) and the skill it brings at its level (技能-1). Throws for an elite phase it does not have or a skill
 * not unlocked yet.
 * @param {Training} t @param {Build} b @returns {OperatorDef}
 */
export function operatorAt(t, b) {
  const phase = t.phases[b.elite];
  if (!phase) throw new RangeError(`${t.name}: no elite phase ${b.elite}`);
  const slot = b.skill >= 0 ? t.skills[b.skill] : undefined;
  if (b.skill >= 0 && (!slot || slot.phase > b.elite)) throw new RangeError(`${t.name}: skill ${b.skill} is not unlocked at elite ${b.elite}`);
  const s = statsAt(t, b), level = slot ? slot.levels[clamp(b.skillLevel, 1, slot.levels.length) - 1] : null;
  return withTrait({
    name: t.name, position: t.position, profession: t.profession, branch: t.branch, range: phase.range, traitBb: traitAt(t, b),
    maxHp: s.maxHp, atk: s.atk, def: s.def, res: s.res, cost: s.cost, blockCnt: s.blockCnt, baseAttackTime: s.baseAttackTime,
    respawnTime: s.respawnTime, aspd: s.aspd, tauntLevel: s.tauntLevel, massLevel: s.massLevel,
    ...(slot && level ? { skill: skillDefOf(slot.id, level) } : {}),
  });
}
